// Opt-in mutation check: one scroll purchase/sale and repair of existing damaged gear.
#include "client.hpp"
#include "assets.hpp"
#include "pathfinding.hpp"
#include <fstream>
#include <iostream>
#include <thread>
#include <sys/stat.h>
#include <unistd.h>
#include <cmath>
using namespace mu::client;
void need(bool b,const char* m){if(!b)throw std::runtime_error(m);}
void pumpFor(Session& s,double seconds){auto end=std::chrono::steady_clock::now()+std::chrono::duration<double>(seconds);while(std::chrono::steady_clock::now()<end){s.pump();std::this_thread::sleep_for(std::chrono::milliseconds(25));}}
void openNpc(Session& s,const mu::assets::Terrain& terrain,unsigned type,unsigned nx,unsigned ny){auto state=s.state();std::vector<unsigned> route;bool reachable=false;for(int y=int(ny)-4;y<=int(ny)+4;y++)for(int x=int(nx)-4;x<=int(nx)+4;x++){if(std::hypot(double(x)-nx,double(y)-ny)>4)continue;auto candidate=mu::viewer::find_path(terrain.attributes,state.x,state.y,x,y);if((!candidate.empty()||(state.x==unsigned(x)&&state.y==unsigned(y)))&&(!reachable||candidate.size()<route.size())){route=std::move(candidate);reachable=true;}}need(reachable,"No reachable tile near shop NPC");for(std::size_t i=0;i<route.size();i+=14){auto end=std::min(i+14,route.size());std::vector<unsigned> steps(route.begin()+i,route.begin()+end);state=s.movePath(state.x,state.y,steps);pumpFor(s,steps.size()*.52+.25);}pumpFor(s,1);state=s.state();unsigned npc=0;bool found=false;for(auto& e:state.viewport->entities)if(e.second.type==type){npc=e.first;found=true;break;}need(found,"Shop NPC outside viewport");s.talk(npc);pumpFor(s,1);state=s.state();need(state.npc.replied&&state.npc.result==0&&state.npc.itemsReady,"Shop did not open");}
int main(int argc,char** argv){try{
 need(argc==2||argc==3,"Usage: MuClient-shop-test PRIVATE_CREDENTIALS [--repair-only]");struct stat st{};need(!stat(argv[1],&st)&&st.st_uid==getuid()&&!(st.st_mode&077),"Credentials must be owner-only");std::ifstream file(argv[1]);std::string account,password;std::getline(file,account);std::getline(file,password);need(account=="muverify","Only isolated test account permitted");auto p=load_profile();Session s(p,0);need(s.login(account,password)==1,"Close GUI session before shop test");std::fill(password.begin(),password.end(),0);auto entry=s.select("MuOptions");need(entry.map==0,"MuOptions must be in Lorencia");pumpFor(s,1);auto terrain=mu::assets::load_terrain(std::filesystem::path(p.assetDirectory)/"Data",0);
 if(argc==3){need(std::string(argv[2])=="--repair-only","Unknown option");openNpc(s,terrain,251,116,141);auto state=s.state();unsigned slot=76;for(auto& item:state.inventory->items)if(item.second.index==11*512&&item.second.durability<48){slot=item.first;break;}need(slot<76,"Damaged boots fixture missing");auto old=state.inventory->items.at(slot).durability;auto money=state.money;need(s.repairItem(slot),"Repair did not change server state");state=s.state();need(state.inventory->items.at(slot).durability>old&&state.money<money,"Repair did not restore durability/debit Zen");auto durability=state.inventory->items.at(slot).durability;money=state.money;std::cout<<"Repaired slot="<<slot<<" durability="<<old<<" -> "<<durability<<" Zen="<<money<<std::endl;s.closeTalk();s.requestLogout(1);s.characters();s.select("MuOptions");pumpFor(s,1);state=s.state();need(state.inventory->items.at(slot).durability==durability&&state.money==money,"Repair did not persist after relog");s.requestLogout(2);std::cout<<"PASS: repair, Zen debit and durability persistence after relog.\n";return 0;}
 openNpc(s,terrain,254,118,113);auto state=s.state();unsigned source=120;for(auto& e:*state.npc.items)if(e.second.index==15*512+3){source=e.first;break;}need(source<120,"Original Fire Ball scroll missing from Pasi stock");auto before=state.money;auto count=state.inventory->items.size();auto expected=state.npc.items->at(source);std::cout<<"Pasi stock="<<state.npc.itemCount<<"; Zen before="<<before<<std::endl;
 auto destination=s.buyItem(source);state=s.state();need(destination>=12&&destination<76,"Purchase rejected; no new ordinary item slot");need(state.inventory->items.at(destination).index==expected.index&&state.inventory->items.size()==count+1,"Purchase ACK did not populate inventory");need(state.money<before,"Server did not debit Zen");auto money=state.money;std::cout<<"Bought item="<<expected.index<<" destination="<<destination<<" cost="<<before-money<<" Zen remaining="<<money<<std::endl;
 s.closeTalk();s.requestLogout(1);s.characters();s.select("MuOptions");pumpFor(s,1);state=s.state();need(state.inventory->items.count(destination)&&state.inventory->items.at(destination).index==expected.index&&state.money==money,"Purchase failed persistence check");
 openNpc(s,terrain,254,118,113);need(s.sellItem(destination),"Sale rejected; purchased scroll remains in bag");state=s.state();need(!state.inventory->items.count(destination)&&state.money>money,"Sale did not remove item/credit Zen");std::cout<<"Sale confirmed; Zen credit="<<state.money-money<<std::endl;s.closeTalk();
 openNpc(s,terrain,251,116,141);state=s.state();unsigned repair=76;for(auto& e:state.inventory->items)if(e.second.index==11*512&&e.second.durability<48){repair=e.first;break;}need(repair<76,"No damaged Bronze Boots fixture");auto oldDur=state.inventory->items.at(repair).durability;auto oldMoney=state.money;need(s.repairItem(repair),"Repair not confirmed (inspect Zen and durability)");state=s.state();need(state.inventory->items.at(repair).durability>oldDur&&state.money<oldMoney,"Repair did not restore durability/debit Zen");auto durability=state.inventory->items.at(repair).durability;money=state.money;std::cout<<"Repair slot="<<repair<<" durability="<<oldDur<<" -> "<<durability<<" cost="<<oldMoney-money<<std::endl;
 s.closeTalk();s.requestLogout(1);s.characters();s.select("MuOptions");pumpFor(s,1);state=s.state();need(!state.inventory->items.count(destination)&&state.inventory->items.at(repair).durability==durability&&state.money==money,"Sale/repair failed persistence check");s.requestLogout(2);std::cout<<"PASS: real shop purchase, sale, repair, Zen accounting and persistence after relog. Original items retained; test scroll sold back.\n";return 0;
 }catch(const std::exception& e){std::cerr<<"Shop test: "<<e.what()<<"\n";return 1;}}
